// =====================================================================
//  CONFIG  —  the only node you should need to edit.
//  The same Config node is used in all four workflows. Edit it once,
//  then copy/paste the node into the other three so they stay in sync.
//
//  WHY a Code node instead of a "Set" node: it lets every setting carry
//  a comment explaining what it does, and it can hold lists and objects.
// =====================================================================

const config = {
  // ---------- ACCOUNT ----------
  // Google Ads customer ID of the CLIENT account, digits only (no dashes).
  customer_id: '1234567890',
  // Your manager (MCC) account ID, digits only. Required when you reach the
  // client account through a manager account (the normal agency setup).
  login_customer_id: '0987654321',
  // Developer token from Google Ads > Tools > API Center (in the MCC).
  // Better: store it as an n8n Variable and use $vars.GOOGLE_ADS_DEV_TOKEN.
  developer_token: 'PASTE_DEVELOPER_TOKEN_HERE',
  // Google ships a new API version roughly monthly; each major version lives
  // about a year. If requests start failing with "version not found",
  // bump this (v25 is supported into Aug 2027).
  api_version: 'v25',
  account_timezone: 'America/Los_Angeles',
  currency: 'USD',

  // ---------- SAFETY SWITCHES ----------
  // DRY RUN = true: every change is sent with validateOnly, so Google CHECKS
  // it but changes nothing. Leave this on for the first 1–2 weeks and read
  // the logs. Flip to false only once the proposals look right to you.
  dry_run: true,
  approver_email: 'you@example.com',
  // Shared secret for runs started from the Blue Market Ads app.
  // Must match N8N_WEBHOOK_SECRET in Vercel.
  webhook_secret: 'PASTE_THE_SAME_SECRET_AS_VERCEL',
  // Hard limits the robot can never exceed, no matter what the math says.
  max_bid_increase_pct: 15,      // per run, per keyword
  max_bid_decrease_pct: 25,      // per run, per keyword
  max_cpc_ceiling: 25.00,        // absolute max bid in dollars
  min_cpc_floor: 0.50,
  max_budget_change_pct: 25,     // per run, per budget
  max_changes_per_run: 40,       // stops a bad run from doing 500 edits

  // ---------- BUSINESS GOALS (Firm Media baseline) ----------
  monthly_budget_total: 3000,    // client's monthly ad budget, in dollars
  target_cpa: 250,               // baseline cost per lead
  // Campaigns whose name contains a key get their own CPA target.
  // High-value procedures can afford more per lead; low-margin ones less.
  cpa_overrides: {
    'All-on-4': 600,
    'Implant': 450,
    'Cleaning': 120,
  },
  target_ctr: 0.07,              // 7% CTR benchmark
  call_min_seconds: 60,          // calls shorter than this are not leads
  // Bid strategy ladder thresholds (conversions in last 30 days)
  conv_for_max_conversions: 15,
  conv_for_target_cpa: 30,

  // ---------- DECISION THRESHOLDS ----------
  // How much a keyword may spend with zero conversions before action.
  // Expressed as a multiple of the campaign's target CPA.
  zero_conv_reduce_at: 1.0,      // lower its bid
  zero_conv_pause_at: 1.5,       // propose pausing it
  min_impr_for_ctr_check: 200,
  min_impr_for_qs_check: 100,
  odd_penny_bids: true,          // $12.00 -> $12.01 (tie-breaker habit)

  // ---------- AI SEARCH-TERM REVIEW ----------
  anthropic_model: 'claude-sonnet-5-5',
  // Tell Claude what the business sells so it can judge search intent.
  business_context:
    'Dental/periodontal practice. Sells: dental implants, All-on-4, gum ' +
    'grafting, periodontal treatment, cleanings. Wants new-patient ' +
    'consultations in the local service area. Does NOT want job seekers, ' +
    'students, DIY/home remedy seekers, or people looking for free care.',
  // Search terms containing these are always proposed as negatives.
  negative_seed_terms: [
    'job', 'jobs', 'career', 'careers', 'salary', 'hiring', 'school',
    'course', 'training', 'certification', 'free', 'diy', 'home remedy',
    'reddit', 'youtube', 'wikipedia', 'pdf', 'definition', 'meaning',
    'cartoon', 'clipart',
  ],

  // ---------- GOOGLE SHEET (change log + lead evaluation) ----------
  // One spreadsheet with two tabs: "Change Log" and "Leads".
  sheet_url: 'https://docs.google.com/spreadsheets/d/PASTE_SHEET_ID/edit',
  log_sheet_tab: 'Change Log',
  lead_sheet_tab: 'Leads',

  // ---------- OFFLINE REVENUE (Workflow 4) ----------
  // Map each lead stage in the sheet to a conversion action ID
  // (Google Ads > Goals > Conversions > click the action > ID in the URL "ctId=").
  // Workflow 3 can create these three actions for you.
  stage_to_conversion_action: {
    'Qualified Lead': '111111111',
    'Booked Consult': '222222222',
    'Closed - Revenue': '333333333',
  },
  // Offset of the sheet's timestamps from UTC (PDT = -07:00, PST = -08:00).
  sheet_utc_offset: '-07:00',
};

// ---------- GAQL QUERIES (Google Ads Query Language) ----------
// Think of these as SQL for your ad account. You rarely need to edit them.
config.queries = {
  // Whole-account spend this month — includes paused/removed campaigns,
  // because that money counts against the client's budget too.
  account_mtd: `
    SELECT metrics.cost_micros, metrics.conversions
    FROM customer
    WHERE segments.date DURING THIS_MONTH`,
  campaigns_mtd: `
    SELECT campaign.id, campaign.name, campaign.status,
           campaign.advertising_channel_type, campaign.bidding_strategy_type,
           campaign.target_spend.cpc_bid_ceiling_micros,
           campaign_budget.resource_name, campaign_budget.amount_micros,
           campaign_budget.explicitly_shared,
           metrics.cost_micros, metrics.clicks, metrics.impressions,
           metrics.conversions, metrics.conversions_value,
           metrics.search_impression_share,
           metrics.search_budget_lost_impression_share,
           metrics.search_rank_lost_impression_share, metrics.average_cpc
    FROM campaign
    WHERE segments.date DURING THIS_MONTH AND campaign.status = 'ENABLED'`,
  campaigns_30d: `
    SELECT campaign.id, metrics.cost_micros, metrics.clicks,
           metrics.conversions, metrics.conversions_value
    FROM campaign
    WHERE segments.date DURING LAST_30_DAYS AND campaign.status = 'ENABLED'`,
  campaigns_today: `
    SELECT campaign.id, campaign.name, campaign_budget.resource_name,
           campaign_budget.amount_micros, metrics.cost_micros,
           metrics.conversions, metrics.clicks
    FROM campaign
    WHERE segments.date DURING TODAY AND campaign.status = 'ENABLED'`,
  keywords_30d: `
    SELECT campaign.id, campaign.name, ad_group.id, ad_group.name,
           ad_group_criterion.resource_name, ad_group_criterion.criterion_id,
           ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type,
           ad_group_criterion.cpc_bid_micros,
           ad_group_criterion.effective_cpc_bid_micros,
           ad_group_criterion.quality_info.quality_score,
           ad_group_criterion.quality_info.creative_quality_score,
           ad_group_criterion.quality_info.post_click_quality_score,
           ad_group_criterion.quality_info.search_predicted_ctr,
           metrics.impressions, metrics.clicks, metrics.cost_micros,
           metrics.conversions, metrics.ctr, metrics.average_cpc,
           metrics.search_rank_lost_impression_share
    FROM keyword_view
    WHERE segments.date DURING LAST_30_DAYS
      AND ad_group_criterion.status = 'ENABLED'
      AND ad_group.status = 'ENABLED' AND campaign.status = 'ENABLED'`,
  search_terms_30d: `
    SELECT campaign.id, campaign.name, ad_group.id,
           search_term_view.search_term, search_term_view.status,
           metrics.impressions, metrics.clicks, metrics.cost_micros,
           metrics.conversions
    FROM search_term_view
    WHERE segments.date DURING LAST_30_DAYS AND metrics.clicks > 0
    ORDER BY metrics.cost_micros DESC
    LIMIT 400`,
  conversion_actions: `
    SELECT conversion_action.resource_name, conversion_action.id,
           conversion_action.name, conversion_action.status,
           conversion_action.type, conversion_action.category,
           conversion_action.primary_for_goal,
           conversion_action.counting_type,
           conversion_action.phone_call_duration_seconds,
           conversion_action.value_settings.default_value,
           conversion_action.click_through_lookback_window_days
    FROM conversion_action
    WHERE conversion_action.status != 'REMOVED'`,
  conversions_by_action_14d: `
    SELECT segments.conversion_action, segments.conversion_action_name,
           metrics.all_conversions
    FROM customer
    WHERE segments.date DURING LAST_14_DAYS`,
  customer_settings: `
    SELECT customer.id, customer.descriptive_name,
           customer.auto_tagging_enabled,
           customer.conversion_tracking_setting.enhanced_conversions_for_leads_enabled,
           customer.conversion_tracking_setting.accepted_customer_data_terms
    FROM customer`,
};

// ---------- STARTED FROM THE APP? ----------
// When the Blue Market Ads app starts this workflow, it sends the account
// to work on. The secret check stops anyone else from triggering it.
const body = $input.first()?.json?.body;
if (body && typeof body === 'object' && body.customer_id) {
  if (!config.webhook_secret || body.secret !== config.webhook_secret) {
    throw new Error('Webhook secret does not match. Run refused.');
  }
  config.customer_id = String(body.customer_id).replace(/\D/g, '');
  config.login_customer_id = String(body.login_customer_id || body.customer_id).replace(/\D/g, '');
  config.started_by = body.requested_by || 'Blue Market Ads app';
  config.account_name = body.account_name || '';
}

return [{ json: config }];

// =====================================================================
//  RULES ENGINE  —  turns raw Google Ads data into proposed changes.
//
//  WHY rules in code AND an AI later: math decisions (CPA, pacing, bid
//  sizes) must be exact and repeatable, so plain code does them. Judgment
//  calls ("is 'implant dentist salary' a customer?") need language
//  understanding, so only those go to Claude in the next node.
//
//  Every proposal carries:
//    - a plain-English reason (goes in your approval email)
//    - the exact Google Ads API operation that would carry it out
// =====================================================================

const cfg = $('Config').first().json;
const rows = (name) => ($(name).first().json.results || []);

const campMtd = rows('Get Campaigns (Month)');
const camp30 = rows('Get Campaigns (30 Days)');
const keywords = rows('Get Keywords');
const terms = rows('Get Search Terms');

// ---------- small helpers ----------
const n = (v) => Number(v || 0);                 // API sends int64 as strings
const usd = (micros) => n(micros) / 1e6;         // 1 dollar = 1,000,000 micros
const money = (x) => '$' + x.toFixed(2);
const pct = (x) => (x * 100).toFixed(1) + '%';
const cid = cfg.customer_id;

// Round a dollar bid to whole cents, optionally to an "odd penny" (.x1).
// Google requires bids in multiples of 10,000 micros (= 1 cent).
function toBidMicros(dollars) {
  let cents = Math.round(dollars * 100);
  cents = Math.min(cents, Math.round(cfg.max_cpc_ceiling * 100));
  cents = Math.max(cents, Math.round(cfg.min_cpc_floor * 100));
  if (cfg.odd_penny_bids && cents % 10 === 0) cents += 1;
  return String(cents * 10000);
}

// Which CPA target applies to this campaign?
function targetCpaFor(campaignName) {
  for (const [key, val] of Object.entries(cfg.cpa_overrides || {})) {
    if ((campaignName || '').toLowerCase().includes(key.toLowerCase())) return val;
  }
  return cfg.target_cpa;
}

// Today's date in the ACCOUNT's timezone (not the server's).
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: cfg.account_timezone, year: 'numeric', month: 'numeric', day: 'numeric',
  }).formatToParts(new Date()).map((p) => [p.type, p.value])
);
const year = n(parts.year), month = n(parts.month), day = n(parts.day);
const daysInMonth = new Date(year, month, 0).getDate();
const daysLeft = daysInMonth - day + 1;          // includes today

const proposals = [];        // changes that need your approval
const recommendations = [];  // advice only — a human decides and acts
let seq = 0;
const add = (p) => proposals.push({ id: ++seq, ...p });

// ---------- index 30-day campaign data ----------
const c30 = {};
for (const r of camp30) c30[r.campaign.id] = r.metrics || {};

// =====================================================================
//  1. CAMPAIGN LEVEL — bid-strategy ladder, impression share, budgets
// =====================================================================
const campaignInfo = {};
let totalDailyBudget = 0;
const seenBudgets = new Set();

for (const r of campMtd) {
  const c = r.campaign, m = r.metrics || {}, b = r.campaignBudget || {};
  const id = c.id;
  const tCpa = targetCpaFor(c.name);
  const conv30 = n(c30[id]?.conversions);
  const cost30 = usd(c30[id]?.costMicros);
  const cpa30 = conv30 > 0 ? cost30 / conv30 : null;
  const strategy = c.biddingStrategyType;
  campaignInfo[id] = { name: c.name, strategy, tCpa, conv30, cpa30, cost30 };

  if (!seenBudgets.has(b.resourceName)) {
    seenBudgets.add(b.resourceName);
    totalDailyBudget += usd(b.amountMicros);
  }

  // --- Bid strategy ladder (Firm Media rule + the next rungs) ---
  // Manual CPC -> Max Conversions at 15+ conv/30d -> Target CPA at 30+.
  // These are big changes that reset Google's learning, so they are
  // RECOMMENDATIONS, never automatic.
  if (strategy === 'MANUAL_CPC' && conv30 >= cfg.conv_for_max_conversions) {
    recommendations.push(`${c.name}: ${conv30.toFixed(0)} conversions in 30 days ` +
      `(threshold ${cfg.conv_for_max_conversions}). Ready to move from Manual CPC to ` +
      `Maximize Conversions. Change it in the UI, then leave it alone for 2 weeks.`);
  }
  if (strategy === 'MAXIMIZE_CONVERSIONS' && conv30 >= cfg.conv_for_target_cpa && cpa30) {
    const suggested = Math.max(cpa30 * 1.05, 1);
    recommendations.push(`${c.name}: ${conv30.toFixed(0)} conversions at ${money(cpa30)} CPA. ` +
      `Add a Target CPA of about ${money(suggested)} (current CPA + 5%). Do NOT start ` +
      `at your dream CPA — a target far below reality starves the campaign of traffic. ` +
      `Lower it 10% every 2–3 weeks while volume holds.`);
  }
  if (strategy === 'MAXIMIZE_CONVERSIONS' && conv30 < cfg.conv_for_max_conversions) {
    recommendations.push(`${c.name}: on Maximize Conversions with only ${conv30.toFixed(0)} ` +
      `conversions in 30 days. Too little data for the algorithm — consider returning to ` +
      `Manual CPC or Max Clicks with a bid ceiling until volume grows.`);
  }
  if (strategy === 'TARGET_SPEND' && !n(c.targetSpend?.cpcBidCeilingMicros)) {
    recommendations.push(`${c.name}: Maximize Clicks has NO max CPC ceiling. Set one ` +
      `(e.g. your average CPC × 1.5) so a single click can't eat the budget.`);
  }

  // --- Impression share diagnosis: WHY are we missing searches? ---
  const lostBudget = n(m.searchBudgetLostImpressionShare);
  const lostRank = n(m.searchRankLostImpressionShare);
  if (lostBudget > 0.15 && cpa30 && cpa30 <= tCpa) {
    recommendations.push(`${c.name}: losing ${pct(lostBudget)} of searches to BUDGET while ` +
      `CPA (${money(cpa30)}) beats target (${money(tCpa)}). This is your best place to ` +
      `add money — every extra dollar here buys leads under target.`);
  }
  if (lostRank > 0.30) {
    recommendations.push(`${c.name}: losing ${pct(lostRank)} of searches to AD RANK. ` +
      `Raising Quality Score is cheaper than raising bids — see the Quality Score notes.`);
  }

  // --- Firm Media budget formula as a sanity check ---
  const avgCpc = usd(m.averageCpc);
  if (avgCpc > 0) {
    const formula = avgCpc * 10 * 30.4;
    campaignInfo[id].formulaBudget = formula;
  }
}

// =====================================================================
//  2. BUDGET PACING — spend 100% of the month, not 80% and not 120%
// =====================================================================
// Each budget's share of the monthly total = its share of current daily
// budgets. New daily = (its share of the monthly budget − what it has
// already spent this month) ÷ days left.
const budgetSpend = {}; const budgetAmt = {}; const budgetNames = {}; const budgetCamps = {};
for (const r of campMtd) {
  const b = r.campaignBudget || {};
  budgetSpend[b.resourceName] = (budgetSpend[b.resourceName] || 0) + usd(r.metrics?.costMicros);
  budgetAmt[b.resourceName] = usd(b.amountMicros);
  (budgetNames[b.resourceName] ||= []).push(r.campaign.name);
  (budgetCamps[b.resourceName] ||= []).push(r.campaign.id);
}
const enabledSpend = Object.values(budgetSpend).reduce((a, x) => a + x, 0);
// Account-wide spend includes campaigns paused earlier this month. Their
// spend still counts against the client's monthly budget.
const spentMtd = Math.max(rows('Get Account Spend (Month)')
  .reduce((a, r) => a + usd(r.metrics?.costMicros), 0), enabledSpend);
const available = Math.max(cfg.monthly_budget_total - (spentMtd - enabledSpend), 0);
const projected = day > 1 ? (spentMtd / (day - 1)) * daysInMonth : 0;

// PERFORMANCE-WEIGHTED POOL (beyond the baseline strategy):
// The money left this month is one daily "pool". Each budget gets a slice
// sized by its current budget × how well it hits its CPA target. A campaign
// at half its target CPA gets up to 1.5× weight; one at double its target
// gets 0.5×. Result: on a limited budget, dollars drift toward the
// campaigns that turn them into leads most cheaply.
const dailyPool = Math.max(available - enabledSpend, 0) / daysLeft;
const perf = {};
for (const res of Object.keys(budgetAmt)) {
  const factors = budgetCamps[res].map((id) => {
    const ci = campaignInfo[id];
    if (ci.cpa30) return Math.min(Math.max(ci.tCpa / ci.cpa30, 0.5), 1.5);
    return ci.cost30 > ci.tCpa ? 0.5 : 1;   // spent a lot, no leads -> penalize
  });
  perf[res] = factors.reduce((a, x) => a + x, 0) / factors.length;
}
const weightTotal = Object.entries(budgetAmt).reduce((a, [res, d]) => a + d * perf[res], 0);

for (const [res, daily] of Object.entries(budgetAmt)) {
  if (!weightTotal || !daily) continue;
  const share = (daily * perf[res]) / weightTotal;
  const monthlyShare = budgetSpend[res] + dailyPool * daysLeft * share;
  let ideal = dailyPool * share;
  // Respect the per-run change limit
  const maxUp = daily * (1 + cfg.max_budget_change_pct / 100);
  const maxDown = daily * (1 - cfg.max_budget_change_pct / 100);
  ideal = Math.min(Math.max(ideal, maxDown), maxUp);
  const change = (ideal - daily) / daily;
  // Never pour more money into a budget whose campaigns are missing their
  // CPA target. Underspending is better than overspending on bad leads.
  if (change > 0) {
    const poor = budgetCamps[res].map((id) => campaignInfo[id]).find((ci) =>
      (ci.cpa30 && ci.cpa30 > ci.tCpa * 1.3) || (!ci.conv30 && ci.cost30 > ci.tCpa * 2));
    if (poor) {
      recommendations.push(`${poor.name}: under-spending, but performance is off target ` +
        `(${poor.cpa30 ? 'CPA $' + poor.cpa30.toFixed(2) : 'no conversions'}). Budget NOT raised. ` +
        `Fix keywords/landing page first, or move this money to a campaign that is hitting target.`);
      continue;
    }
  }
  if (Math.abs(change) >= 0.10) {
    const cents = Math.max(Math.round(ideal * 100), 100);
    add({
      type: 'SET_BUDGET',
      campaign_name: budgetNames[res].join(', '),
      summary: `Daily budget ${money(daily)} → ${money(cents / 100)}`,
      reason: `Pacing: ${money(budgetSpend[res])} spent so far, ${daysLeft} days left. ` +
        `Performance weight ${perf[res].toFixed(2)}× (CPA vs target) — ` +
        `${perf[res] >= 1 ? 'protected as a strong performer' : 'trimmed first because it is over its CPA target'}. ` +
        `Lands the month on budget.`,
      direction: change > 0 ? 'up' : 'down',
      endpoint: 'campaignBudgets:mutate',
      operation: { update: { resourceName: res, amountMicros: String(cents * 10000) },
                   updateMask: 'amountMicros' },
    });
  }
}

// =====================================================================
//  3. KEYWORD LEVEL — bids, pauses, CTR and Quality Score
// =====================================================================
const existingKeywords = new Set();
for (const r of keywords) {
  const k = r.adGroupCriterion || {}, m = r.metrics || {};
  const camp = campaignInfo[r.campaign.id] || { name: r.campaign.name, strategy: '' };
  const text = k.keyword?.text || '';
  existingKeywords.add(text.toLowerCase());
  const tCpa = targetCpaFor(camp.name);
  const cost = usd(m.costMicros), conv = n(m.conversions);
  const clicks = n(m.clicks), impr = n(m.impressions), ctr = n(m.ctr);
  const label = `"${text}" [${k.keyword?.matchType}] in ${camp.name}`;

  // Keyword bids only matter on MANUAL CPC. On Smart Bidding Google
  // ignores them, so changing them would do nothing.
  const manual = camp.strategy === 'MANUAL_CPC';
  const bid = usd(k.cpcBidMicros || k.effectiveCpcBidMicros);

  // --- Zero-conversion spenders ---
  if (conv === 0 && cost >= tCpa * cfg.zero_conv_pause_at) {
    add({
      type: 'PAUSE_KEYWORD', campaign_name: camp.name,
      summary: `Pause ${label}`,
      reason: `Spent ${money(cost)} (${clicks} clicks) with 0 conversions — over ` +
        `${cfg.zero_conv_pause_at}× the ${money(tCpa)} target CPA. Statistically it ` +
        `should have converted by now.`,
      endpoint: 'adGroupCriteria:mutate',
      operation: { update: { resourceName: k.resourceName, status: 'PAUSED' }, updateMask: 'status' },
    });
    continue;
  }
  if (manual && bid > 0 && conv === 0 && cost >= tCpa * cfg.zero_conv_reduce_at) {
    const newBid = bid * (1 - cfg.max_bid_decrease_pct / 100);
    add({
      type: 'BID_DOWN', campaign_name: camp.name,
      summary: `Bid ${money(bid)} → ${money(usd(toBidMicros(newBid)))} on ${label}`,
      reason: `Spent ${money(cost)} with 0 conversions (≥ 1× target CPA). Cheaper clicks ` +
        `buy more chances to convert before deciding to pause.`,
      endpoint: 'adGroupCriteria:mutate',
      operation: { update: { resourceName: k.resourceName, cpcBidMicros: toBidMicros(newBid) },
                   updateMask: 'cpcBidMicros' },
    });
    continue;
  }

  // --- Converting keywords: steer CPA toward target ---
  if (manual && bid > 0 && conv >= 1) {
    const cpa = cost / conv;
    if (cpa > tCpa * 1.3) {
      // Scale the bid by target/actual, capped by the per-run limit.
      const factor = Math.max(tCpa / cpa, 1 - cfg.max_bid_decrease_pct / 100);
      add({
        type: 'BID_DOWN', campaign_name: camp.name,
        summary: `Bid ${money(bid)} → ${money(usd(toBidMicros(bid * factor)))} on ${label}`,
        reason: `CPA ${money(cpa)} is ${((cpa / tCpa - 1) * 100).toFixed(0)}% over the ` +
          `${money(tCpa)} target (${conv.toFixed(1)} conv).`,
        endpoint: 'adGroupCriteria:mutate',
        operation: { update: { resourceName: k.resourceName, cpcBidMicros: toBidMicros(bid * factor) },
                     updateMask: 'cpcBidMicros' },
      });
    } else if (cpa < tCpa * 0.7 && n(m.searchRankLostImpressionShare) > 0.2) {
      const factor = 1 + cfg.max_bid_increase_pct / 100;
      add({
        type: 'BID_UP', campaign_name: camp.name,
        summary: `Bid ${money(bid)} → ${money(usd(toBidMicros(bid * factor)))} on ${label}`,
        reason: `Winner: CPA ${money(cpa)} is well under target, yet it misses ` +
          `${pct(n(m.searchRankLostImpressionShare))} of searches to ad rank. More of ` +
          `these clicks = more leads under target.`,
        direction: 'up',
        endpoint: 'adGroupCriteria:mutate',
        operation: { update: { resourceName: k.resourceName, cpcBidMicros: toBidMicros(bid * factor) },
                     updateMask: 'cpcBidMicros' },
      });
    }
  }

  // --- Low CTR: an ad/keyword relevance problem, not a bid problem ---
  if (impr >= cfg.min_impr_for_ctr_check && ctr < cfg.target_ctr) {
    if (ctr < cfg.target_ctr / 2) {
      recommendations.push(`${label}: CTR ${pct(ctr)} on ${impr} impressions (target ` +
        `${pct(cfg.target_ctr)}). Ads don't match this search — write an ad group/ad that ` +
        `repeats this keyword in the headline, or tighten the match type.`);
    }
  }

  // --- Quality Score: diagnose WHICH of the 3 parts is weak ---
  const qs = n(k.qualityInfo?.qualityScore);
  if (qs && qs <= 5 && impr >= cfg.min_impr_for_qs_check) {
    const qi = k.qualityInfo;
    const weak = [];
    if (qi.searchPredictedCtr === 'BELOW_AVERAGE') weak.push('expected CTR (stronger, more specific headlines)');
    if (qi.creativeQualityScore === 'BELOW_AVERAGE') weak.push('ad relevance (put the keyword in the ad)');
    if (qi.postClickQualityScore === 'BELOW_AVERAGE') weak.push('landing page (speed, message match, CTA above the fold)');
    recommendations.push(`${label}: Quality Score ${qs}/10. Weak: ${weak.join('; ') || 'average across the board'}.`);
  }
}

// =====================================================================
//  4. SEARCH TERMS — negatives (waste) and new keywords (expansion)
// =====================================================================
const candidates = [];
const seeds = (cfg.negative_seed_terms || []).map((s) => s.toLowerCase());
const negSeen = new Set();
for (const r of terms) {
  const st = r.searchTermView || {}, m = r.metrics || {};
  const term = (st.searchTerm || '').toLowerCase();
  const camp = campaignInfo[r.campaign.id] || { name: r.campaign.name };
  const tCpa = targetCpaFor(camp.name);
  const cost = usd(m.costMicros), conv = n(m.conversions), clicks = n(m.clicks);
  if (st.status === 'EXCLUDED') continue;

  const words = term.split(/\s+/);
  const seedHit = seeds.find((s) => (s.includes(' ') ? term.includes(s) : words.includes(s)));
  const key = r.campaign.id + '|' + term;

  if (seedHit && conv === 0 && !negSeen.has(key)) {
    negSeen.add(key);
    add({
      type: 'ADD_NEGATIVE', campaign_name: camp.name,
      summary: `Negative [exact] "${term}"`,
      reason: `Contains blocked word "${seedHit}". ${money(cost)} spent, 0 conversions.`,
      endpoint: 'campaignCriteria:mutate',
      operation: { create: { campaign: `customers/${cid}/campaigns/${r.campaign.id}`,
        negative: true, keyword: { text: term, matchType: 'EXACT' } } },
    });
  } else if (conv === 0 && clicks >= 2 && cost >= tCpa * 0.2) {
    // Not obviously junk — let Claude judge the intent.
    candidates.push({ term, campaign_id: r.campaign.id, campaign: camp.name,
                      clicks, cost: +cost.toFixed(2) });
  } else if (conv >= 1 && st.status !== 'ADDED' && !existingKeywords.has(term)) {
    // EXPANSION: a real search that already produced a lead but isn't a
    // keyword yet. Adding it as EXACT gives you control of its bid and ad.
    const cpc = clicks ? cost / clicks : cfg.min_cpc_floor;
    add({
      type: 'ADD_KEYWORD', campaign_name: camp.name,
      summary: `New keyword [exact] "${term}" at ${money(usd(toBidMicros(cpc)))}`,
      reason: `Already converted ${conv.toFixed(1)}× at ${money(cost / conv)} per lead ` +
        `through a broader keyword. Owning it as exact match lets you bid on it directly.`,
      endpoint: 'adGroupCriteria:mutate',
      operation: { create: { adGroup: `customers/${cid}/adGroups/${r.adGroup.id}`,
        status: 'ENABLED', keyword: { text: term, matchType: 'EXACT' },
        cpcBidMicros: toBidMicros(cpc) } },
    });
  }
}

// ---------- prompt for Claude (only the ambiguous terms) ----------
const aiCandidates = candidates.slice(0, 150);
const ai_prompt = aiCandidates.length === 0 ? '' :
`You are reviewing Google Ads search terms for wasted spend.

BUSINESS: ${cfg.business_context}

Each search term below got clicks but no conversions. Decide for each one:
- "negative" if the searcher is clearly NOT a potential customer (wrong service,
  job seeker, researcher, DIY, wrong location, competitor brand, etc.)
- "keep" if a real customer could plausibly search this, even if it hasn't
  converted yet.
When unsure, choose "keep" — blocking a good search costs more than a few clicks.

Return ONLY valid JSON, no prose, in exactly this shape:
{"decisions":[{"term":"...","campaign_id":"...","decision":"negative"|"keep",
"match_type":"EXACT"|"PHRASE","reason":"under 15 words"}]}
Use PHRASE only when a word in the term makes every variation irrelevant.

SEARCH TERMS:
${JSON.stringify(aiCandidates)}`;

// ---------- account-level summary for the email ----------
const totalConv30 = Object.values(c30).reduce((a, m) => a + n(m.conversions), 0);
const totalCost30 = Object.values(c30).reduce((a, m) => a + usd(m.costMicros), 0);
const summary = {
  date: `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
  spent_mtd: +spentMtd.toFixed(2),
  monthly_budget: cfg.monthly_budget_total,
  projected_month_end: +projected.toFixed(2),
  conversions_30d: +totalConv30.toFixed(1),
  cpa_30d: totalConv30 ? +(totalCost30 / totalConv30).toFixed(2) : null,
  campaigns: Object.keys(campaignInfo).length,
  keywords_reviewed: keywords.length,
  search_terms_reviewed: terms.length,
};

return [{ json: { summary, proposals, recommendations, ai_candidates: aiCandidates, ai_prompt } }];

// =====================================================================
//  MERGE AI + BUILD APPROVAL EMAIL
//  Adds Claude's negative-keyword picks to the rule-based proposals,
//  applies the safety cap, and writes the email you approve or reject.
// =====================================================================

const cfg = $('Config').first().json;
const base = $('Rules Engine').first().json;
const proposals = [...base.proposals];
const cid = cfg.customer_id;

// ---------- read Claude's answer (fail safe: no answer = no AI changes) ----------
let aiNote = '';
try {
  const resp = $('AI Search Term Review').first().json;
  if (resp.error) throw new Error(resp.error.message || 'API error');
  const text = (resp.content || []).map((c) => c.text || '').join('');
  if (text.trim()) {
    // Claude sometimes wraps JSON in ```json fences — strip them.
    const clean = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean.slice(clean.indexOf('{'), clean.lastIndexOf('}') + 1));
    // Only accept terms we actually sent. Never trust an AI to invent targets.
    const allowed = new Map(base.ai_candidates.map((c) => [c.campaign_id + '|' + c.term, c]));
    let added = 0;
    for (const d of parsed.decisions || []) {
      const cand = allowed.get(String(d.campaign_id) + '|' + String(d.term).toLowerCase());
      if (!cand || d.decision !== 'negative') continue;
      const match = d.match_type === 'PHRASE' ? 'PHRASE' : 'EXACT';
      proposals.push({
        id: proposals.length + 1, type: 'ADD_NEGATIVE', campaign_name: cand.campaign,
        summary: `Negative [${match.toLowerCase()}] "${cand.term}" (AI)`,
        reason: `${d.reason || 'Off-intent search'} — $${cand.cost} spent, 0 conversions.`,
        endpoint: 'campaignCriteria:mutate',
        operation: { create: { campaign: `customers/${cid}/campaigns/${cand.campaign_id}`,
          negative: true, keyword: { text: cand.term, matchType: match } } },
      });
      added++;
    }
    aiNote = `Claude reviewed ${base.ai_candidates.length} unclear search terms and flagged ${added}.`;
  }
} catch (e) {
  aiNote = `AI review skipped (${e.message}). Rule-based proposals only.`;
}

// ---------- safety cap: money-saving changes first ----------
const priority = { ADD_NEGATIVE: 1, PAUSE_KEYWORD: 2, BID_DOWN: 3, SET_BUDGET: 4, ADD_KEYWORD: 5, BID_UP: 6 };
proposals.sort((a, b) => priority[a.type] - priority[b.type]);
const kept = proposals.slice(0, cfg.max_changes_per_run);
const dropped = proposals.length - kept.length;
kept.forEach((p, i) => (p.id = i + 1));

// ---------- write the email ----------
const s = base.summary;
const L = [];
L.push(`GOOGLE ADS DAILY OPTIMIZER — ${s.date}`);
L.push(cfg.dry_run ? 'MODE: DRY RUN (approving only tests the changes; nothing goes live)' : 'MODE: LIVE (approving applies these changes)');
L.push('');
L.push('ACCOUNT SNAPSHOT');
L.push(`• Spent this month: $${s.spent_mtd} of $${s.monthly_budget} (projected month-end: $${s.projected_month_end})`);
L.push(`• Last 30 days: ${s.conversions_30d} conversions, CPA ${s.cpa_30d ? '$' + s.cpa_30d : 'n/a'} (target $${cfg.target_cpa})`);
L.push(`• Reviewed ${s.campaigns} campaigns, ${s.keywords_reviewed} keywords, ${s.search_terms_reviewed} search terms`);
if (aiNote) L.push(`• ${aiNote}`);
L.push('');

const groups = {
  ADD_NEGATIVE: 'BLOCK WASTED SEARCHES', PAUSE_KEYWORD: 'PAUSE NON-CONVERTING KEYWORDS',
  BID_DOWN: 'LOWER BIDS', SET_BUDGET: 'BUDGET PACING', ADD_KEYWORD: 'ADD PROVEN SEARCHES AS KEYWORDS',
  BID_UP: 'RAISE BIDS ON WINNERS',
};
if (kept.length === 0) {
  L.push('NO CHANGES PROPOSED TODAY. Approving or rejecting does nothing.');
} else {
  L.push(`PROPOSED CHANGES (${kept.length})`);
  for (const [type, title] of Object.entries(groups)) {
    const list = kept.filter((p) => p.type === type);
    if (!list.length) continue;
    L.push('');
    L.push(`— ${title} —`);
    for (const p of list) {
      L.push(`${p.id}. ${p.summary}  (${p.campaign_name})`);
      L.push(`   Why: ${p.reason}`);
    }
  }
  if (dropped > 0) L.push(`\n(${dropped} lower-priority changes held back by the ${cfg.max_changes_per_run}-change safety cap.)`);
}

if (base.recommendations.length) {
  L.push('');
  L.push('RECOMMENDATIONS (not applied automatically — your call)');
  base.recommendations.slice(0, 25).forEach((r) => L.push(`• ${r}`));
}
L.push('');
L.push('Approve = apply every numbered change above. Reject = change nothing.');

return [{ json: {
  email_subject: `[Ads Optimizer] ${kept.length} changes to review — ${s.date}${cfg.dry_run ? ' (dry run)' : ''}`,
  // Plain text on purpose: n8n's approval email keeps line breaks.
  email_body: L.join('\n'),
  proposals: kept,
  summary: s,
} }];

// =====================================================================
//  BUILD API REQUESTS — runs only after the approval email comes back.
//  Groups approved changes by API endpoint so each endpoint gets ONE
//  request carrying many operations (faster, and fewer API calls).
// =====================================================================

const cfg = $('Config').first().json;
const approval = $input.first().json;
// n8n puts the button result in data.approved. A timeout = no approval.
const approved = approval?.data?.approved === true || approval?.approved === true;
if (!approved) return [];   // returning nothing stops the workflow here

const { proposals } = $('Merge AI + Build Email').first().json;
const byEndpoint = {};
for (const p of proposals) (byEndpoint[p.endpoint] ||= []).push(p);

const out = [];
for (const [endpoint, list] of Object.entries(byEndpoint)) {
  out.push({ json: {
    url: `https://googleads.googleapis.com/${cfg.api_version}/customers/${cfg.customer_id}/${endpoint}`,
    body: {
      operations: list.map((p) => p.operation),
      // partialFailure: one bad operation won't block the good ones.
      partialFailure: true,
      // validateOnly: Google checks everything but changes nothing.
      validateOnly: cfg.dry_run === true,
    },
    endpoint,
    proposal_ids: list.map((p) => p.id),
    summaries: list.map((p) => p.summary),
  } });
}
return out;

// =====================================================================
//  LOG RESULTS — one spreadsheet row per change, so you have a full
//  history of what the system did, when, and whether Google accepted it.
// =====================================================================

const cfg = $('Config').first().json;
const requests = $('Build API Requests').all();
const responses = $input.all();
const rows = [];
const now = new Date().toISOString();

requests.forEach((req, i) => {
  const res = responses[i]?.json || {};
  const results = res.results || [];
  const httpError = res.error ? (res.error.message || JSON.stringify(res.error)).slice(0, 300) : '';
  // With partialFailure, failed operations come back as empty {} results.
  const pfErrors = (res.partialFailureError?.details || [])
    .flatMap((d) => d.errors || []).map((e) => e.message);

  req.json.summaries.forEach((summary, j) => {
    const ok = !httpError && results[j] && Object.keys(results[j]).length > 0;
    rows.push({ json: {
      timestamp: now,
      mode: cfg.dry_run ? 'DRY RUN' : 'LIVE',
      customer_id: cfg.customer_id,
      endpoint: req.json.endpoint,
      change: summary,
      status: httpError ? 'ERROR' : (ok || cfg.dry_run && !pfErrors.length ? 'OK' : 'FAILED'),
      detail: httpError || (ok ? (results[j].resourceName || '') : (pfErrors.shift() || '')),
    } });
  });
});
return rows;
